async function executeChatAction(a){
 let result,undo;
 const {receipt}=require('./task-undo.cjs');
 if(a.type==='note'){const n=utility.addNote(a.title,a.text);if(!n)return {error:'便签最多 30 条。'};result='已记下便签：'+n.title;undo=receipt('note',n);}
 else if(a.type==='todo'){if(!engine.todo('add',a.text))return {error:'待办已存在、为空或达到 50 条上限。'};result='已添加待办：'+a.text;undo=receipt('todo',engine.todos.at(-1));}
 else if(a.type==='reminder'){const r=utility.addAlert(a);if(r.error)return r;undo=receipt('reminder',r.item);result='已安排提醒：'+r.item.text+' · '+(r.item.repeat==='daily'?'每天 '+r.item.time:new Date(r.item.nextAt).toLocaleString('zh-CN'));}
 else if(a.type==='open_link'){const l=utility.links.find(l=>l.id===a.link_id);if(!l)return {error:'入口已删除，请在小工具中重新添加。'};
  if(l.kind==='url'){const url=safeURL(l.target);if(!url)return {error:'网站地址无效。'};await openWebURL(url);}
  else{if(!path.isAbsolute(l.target)||!fs.existsSync(l.target))return {error:'文件已移动或不存在，请重新添加入口。'};const error=await shell.openPath(l.target);if(error)return {error};}result='已打开快捷入口：'+l.label;
 }else return {error:'操作无效。'};
 engine.record(result,Date.now());engine.say(result.slice(0,120),Date.now(),10000);engine.lastVoicePreset=({note:'action-note',todo:'action-todo',reminder:'action-reminder',open_link:'action-link'})[a.type]||'action-done';engine.react({expression:'smile',gesture:'nod'},Date.now());speakInteraction();return {ok:true,result,...(undo?{receipt:undo,evidence:{kind:'local',verified:true,at:Date.now()}}:{})};
}
